<template><section :aria-label="title"><p class="tool-note" v-if="mode==='view'">读取图片携带的 EXIF、GPS、XMP、IPTC 等常见字段，不上传、不自动打开定位地图。最多 25 MiB；格式支持取决于解析器。拍摄时间可能没有时区信息；表格最多显示 300 项，每项较长内容会截断。</p><p class="tool-note" v-else>通过新画布重新编码，原始 EXIF / XMP / IPTC 不复制，生成清理副本；原文件不变。会按浏览器解码结果应用方向。JPEG 会重新压缩，色彩、体积或细节可能变化，PNG 保留解码后的像素；不处理动态图。</p><label class="tool-label">{{mode==='view'?'选择需要查看的图片':'选择需要清理的图片'}}<input type="file" :aria-label="mode==='view'?'选择EXIF查看图片':'选择EXIF清理图片'" :accept="mode==='view'?'.jpg,.jpeg,.png,.webp,.tif,.tiff,.heic,.heif,.avif':'image/jpeg,image/png,image/webp,image/avif'" @change="selectFile" /></label><p v-if="file">{{file.name}} · {{fileSize}}</p><template v-if="mode==='clean'"><div class="tool-actions"><label>导出格式<select v-model="format" :disabled="busy" aria-label="EXIF清理导出格式"><option value="image/png">PNG</option><option value="image/jpeg">JPEG</option><option value="image/webp">WebP</option></select></label><button type="button" :disabled="!file||busy" @click="clean">{{busy?'处理中…':'清理并生成副本'}}</button><button type="button" :disabled="!output" @click="download">下载EXIF清理副本</button></div><template v-if="output"><p>结果 {{output.width}} × {{output.height}} · {{outputSize}} · {{output.blob.type}}。输出再次检测通过，未发现定位字段。</p><p class="tool-note">输出格式的基本属性可能仍存在，不代表原始 EXIF 被保留。</p><img :src="preview" alt="清理后的图片预览" class="metadata-preview" /></template></template><template v-if="mode==='view'&&loaded"><p>解析到 {{rows.length}} 个字段。没有字段可能表示图片未携带这些元数据、已被清理，或格式未被完整支持。</p><label class="tool-label">筛选字段<input v-model="query" aria-label="筛选EXIF字段" placeholder="例如 GPS / Model / Date" /></label><div class="metadata-table"><table><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.tag"><td>{{row.tag}}</td><td>{{row.value}}</td></tr></tbody></table></div><button type="button" :disabled="!rows.length" @click="copy">复制检测信息</button></template><div class="tool-actions"><button type="button" @click="clear">清空{{title}}</button></div><p role="status">{{message}}</p></section></template>
<script>
import {readPhotoMetadata,photoMetadataRows,reencodePhoto} from '../../utils/photo-metadata-tools.mjs';
import {formatBytes,downloadBlob} from '../../utils/utility-tools.mjs';
export default {name:'PhotoMetadataTool',props:{mode:{type:String,required:true}},data:()=>({file:null,metadata:{},query:'',loaded:false,busy:false,message:'',request:0,format:'image/png',output:null,preview:''}),computed:{title(){return this.mode==='view'?'图片 EXIF 信息查看':'图片 EXIF 信息清理';},fileSize(){return this.file?formatBytes(this.file.size):'';},outputSize(){return this.output?formatBytes(this.output.blob.size):'';},rows(){return photoMetadataRows(this.metadata);},filteredRows(){const q=this.query.trim().toLowerCase();return this.rows.filter(r=>(r.tag+' '+r.value).toLowerCase().includes(q));}},watch:{format(){this.resetOutput();this.message='导出格式已更改，请重新生成副本';}},beforeUnmount(){++this.request;if(this.preview)URL.revokeObjectURL(this.preview);},methods:{clear(){++this.request;this.file=null;this.metadata={};this.loaded=false;this.busy=false;this.message='';this.query='';this.resetOutput();},resetOutput(){if(this.preview)URL.revokeObjectURL(this.preview);this.preview='';this.output=null;},async selectFile(event){const request=++this.request;this.file=event.target.files?.[0]||null;event.target.value='';this.resetOutput();this.metadata={};this.loaded=false;this.message='';this.busy=false;if(!this.file)return;if(this.mode==='clean'){this.busy=false;return;}this.busy=true;try{const metadata=await readPhotoMetadata(this.file);if(request===this.request){this.metadata=metadata;this.loaded=true;this.message='元数据读取完成';}}catch(error){if(request===this.request)this.message='读取失败：'+error.message;}finally{if(request===this.request)this.busy=false;}},async clean(){if(!this.file||this.busy)return;const request=++this.request;this.busy=true;this.message='';this.resetOutput();try{const result=await reencodePhoto(this.file,{format:this.format});if(request!==this.request)return;this.output=result;this.preview=URL.createObjectURL(result.blob);this.message='清理副本已生成，原文件未修改';}catch(error){if(request===this.request)this.message='处理失败：'+error.message;}finally{if(request===this.request)this.busy=false;}},download(){const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[this.output.blob.type]||'png';downloadBlob(this.output.blob,'01-clean-image.'+ext);},async copy(){try{await navigator.clipboard.writeText(JSON.stringify(this.rows,null,2));this.message='已复制检测信息';}catch{this.message='复制未完成，请选择表格文字手动复制';}}}};
</script>
<style scoped>.metadata-table{max-height:420px;overflow:auto;margin:12px 0;}table{width:100%;border-collapse:collapse;table-layout:fixed;}th,td{text-align:left;border:1px solid var(--el-border-color);padding:8px;overflow-wrap:anywhere;vertical-align:top;}th:first-child,td:first-child{width:35%;}.metadata-preview{max-width:100%;max-height:320px;object-fit:contain;}</style>
